package com.bank.escalation;

import java.util.*;

public class EscalationChart {

    public List<List<Integer>> bottomUpLevels(AuditNode root) {
        LinkedList<List<Integer>> result = new LinkedList<>();   // deque for O(1) addFirst
        if (root == null) return result;

        Queue<AuditNode> queue = new LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            List<Integer> level = new ArrayList<>();
            for (int i = 0; i < levelSize; i++) {
                AuditNode node = queue.poll();
                level.add(node.id);
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
            result.addFirst(level);    // prepend → bottom level ends up first
        }
        return result;
    }
}
