package com.bank.escalation;

import java.util.logging.Logger;

public class BottomUpDemo {
    private static final Logger log = Logger.getLogger(BottomUpDemo.class.getName());

    public static void main(String[] args) {
        AuditNode root = new AuditNode(1);
        root.left = new AuditNode(2);
        root.right = new AuditNode(3);
        root.left.left = new AuditNode(4);
        root.left.right = new AuditNode(5);
        root.right.right = new AuditNode(6);

        log.info("Bottom-up escalation chart: " + new EscalationChart().bottomUpLevels(root));
    }
}
